use core::sync::atomic::{AtomicU32 as A,Ordering as O};static VALUE:A=A::new(0);struct Pair{x:u32,a:A}static NESTED:Pair=Pair{x:7,a:A::new(11)};fn main(){let _=VALUE.swap(5,O::Acquire);let _=VALUE.fetch_add(3,O::Release);check(VALUE.load(O::Relaxed)==8);let _=NESTED.a.swap(17,O::AcqRel);let _=NESTED.a.fetch_add(6,O::SeqCst);check(NESTED.a.load(O::Relaxed)==23);check(NESTED.x==7);}
